package com.gymmind.knowledge.infrastructure.storage;
import com.gymmind.knowledge.application.KnowledgeObjectStore;
import org.springframework.stereotype.Component;
import java.nio.file.*;
@Component public class LocalObjectStore implements KnowledgeObjectStore { private final Path root=Path.of(System.getProperty("java.io.tmpdir"),"gymmind-objects"); public void put(String key,byte[] content,String type){try{Path p=root.resolve(key).normalize();if(!p.startsWith(root))throw new IllegalArgumentException("invalid object key");Files.createDirectories(p.getParent());Files.write(p,content);}catch(java.io.IOException e){throw new IllegalStateException("object storage failure",e);}} public byte[] read(String key){try{Path p=root.resolve(key).normalize();if(!p.startsWith(root))throw new IllegalArgumentException("invalid object key");return Files.readAllBytes(p);}catch(java.io.IOException e){throw new IllegalStateException("object storage failure",e);}} public void delete(String key){try{Files.deleteIfExists(root.resolve(key).normalize());}catch(java.io.IOException e){throw new IllegalStateException("object storage failure",e);}} }
